@push('scripts')<script>(function(){var size=10;function render(modal,page){var rows=Array.prototype.slice.call(modal.querySelectorAll('.fap-detail-row')),total=rows.length,last=Math.max(1,Math.ceil(total/size));page=Math.max(1,Math.min(page,last));rows.forEach(function(row,i){row.style.display=i>=(page-1)*size&&i<page*size?'':'none';});modal.querySelector('.fap-detail-summary').textContent='显示 '+(total?(page-1)*size+1:0)+'-'+Math.min(page*size,total)+' 条，共 '+total+' 条';var html='';for(var i=1;i<=last;i++)html+='<button class="btn btn-default btn-xs fap-page '+(i===page?'active':'')+'" data-page="'+i+'">'+i+'</button>';modal.querySelector('.fap-detail-pages').innerHTML=html;}$(document).on('show.bs.modal','.fap-detail-modal',function(){render(this,1);});document.addEventListener('click',function(e){var button=e.target.closest('.fap-page');if(button)render(button.closest('.fap-detail-modal'),Number(button.dataset.page));});})();</script>@endpush
